   569  static int decode_bit_string(const u8 * inbuf, size_t inlen, void *outbuf,
   570                               size_t outlen, int invert)
   571  {
   572          const u8 *in = inbuf;
   573          u8 *out = (u8 *) outbuf;
   574          int i, count = 0;
   575          int zero_bits;
   576          size_t octets_left;
   577
   578          if (inlen < 1)
   579                  return SC_ERROR_INVALID_ASN1_OBJECT;
   580          /* 8.6.2.3 If the bitstring is empty, there shall be no subsequent octets,
   581           * and the initial octet shall be zero. */
   582          if (inlen == 1 && *in != 0)
   583                  return SC_ERROR_INVALID_ASN1_OBJECT;
   584          /* ITU-T Rec. X.690 8.6.2.2: The number shall be in the range zero to seven. */
   585          if ((*in & ~0x07) != 0)
   586                  return SC_ERROR_INVALID_ASN1_OBJECT;
   587          memset(outbuf, 0, outlen);
   588          zero_bits = *in & 0x07;
   589          in++;
   590          octets_left = inlen - 1;
   591          if (outlen < octets_left)
   592                  return SC_ERROR_BUFFER_TOO_SMALL;
   593
   594          while (octets_left) {
   595                  /* 1st octet of input:  ABCDEFGH, where A is the MSB */
   596                  /* 1st octet of output: HGFEDCBA, where A is the LSB */
   597                  /* first bit in bit string is the LSB in first resulting octet */
   598                  int bits_to_go;
   599
   600                  *out = 0;
   601                  if (octets_left == 1 && zero_bits > 0) {
   602                          bits_to_go = 8 - zero_bits;
   603                          /* Verify the padding is zero bits */
   604                          if (*in & (1 << (zero_bits-1))) {
   605                                  return SC_ERROR_INVALID_ASN1_OBJECT;
   606                          }
   607                  } else
   608                          bits_to_go = 8;
   609                  if (invert)
   610                          for (i = 0; i < bits_to_go; i++) {
   611                                  *out |= ((*in >> (7 - i)) & 1) << i;
   612                          }
   613                  else {
   614                          *out = *in;
   615                  }
   616                  out++;
   617                  in++;
   618                  octets_left--;
   619                  count++;
   620          }
   621          return (count * 8) - zero_bits;
   622  }
